def sha(p: Path):
    # CRLF-insensitive: Windows checkouts (core.autocrlf) must still match.
    if not p.exists():
        return None
    return hashlib.sha256(p.read_bytes().replace(b"\r\n", b"\n")).hexdigest()


def find_root(arg):
    for c in ([Path(arg)] if arg else []) + [Path.cwd(), Path.cwd().parent,
                                             Path(__file__).resolve().parent]:
        if (c / "backend" / "app" / "execution" / "execution_router.py").exists():
            return c.resolve()
    sys.exit("Could not find the repo root (folder containing backend/app). "
             "Run from the repo root or pass --repo PATH.")


def plan(root):
    todo, done, bad = [], [], []
    for f in FILES:
        p = root / f["path"]
        cur = sha(p)
        if cur == f["new_sha"]:
            done.append(f)
        elif (f["is_new"] and cur is None) or cur in f["ok_bases"]:
            todo.append(f)
        else:
            bad.append((f["path"], "missing" if cur is None else "locally modified / different version"))
    return todo, done, bad


TESTS = [
    ("backend/app/execution", ["test_execution_router_contract.py"]),
    ("backend/app/engine/tma2", ["test_tma2_e2e.py", "test_tma2_exit_paths.py",
                                 "test_tma2_entry_paths.py", "test_tma2_live_core.py"]),
    ("backend/app/engine/tma", ["test_tma_exit_paths.py", "test_tma_live_core.py"]),
    ("backend/app/engine/vet", ["test_vet_e2e.py", "test_vet_live_confirm.py", "test_vet_manager.py",
                                "test_vet_live_dte_lots.py", "test_vet_sltp_live.py"]),
    ("backend/app/engine/tsg", ["test_tsg_e2e.py", "test_tsg_exit_confirm.py", "test_tsg_live_core.py",
                                "test_tsg_sl_per_lot.py"]),
]


def run_tests(root):
    print("\nRunning tests (one to two minutes)…")
    # Every suite runs with a THROWAWAY home folder: some pre-existing repo
    # tests write logs / app.db rows under ~/.scalp-app. Pointing HOME (and
    # USERPROFILE on Windows) at a temp dir keeps your real data untouched.
    import tempfile
    sandbox = tempfile.mkdtemp(prefix="scalp_tests_home_")
    base_env = dict(os.environ, HOME=sandbox, USERPROFILE=sandbox)
    print(f"  (test home: {sandbox} — your real ~/.scalp-app is not touched)")
    fails = 0
    for d, names in TESTS:
        for n in names:
            r = subprocess.run([sys.executable, n], cwd=root / d, env=base_env,
                               capture_output=True, text=True, timeout=900)
            last = (r.stdout.strip().splitlines() or [""])[-1]
            ok = r.returncode == 0
            fails += not ok
            print(f"  {'PASS' if ok else 'FAIL'}  {n}  {last[:90] if ok else ''}")
            if not ok:
                print("        " + "\n        ".join((r.stdout + r.stderr).strip().splitlines()[-12:]))
    ic = root / "backend/app/engine/ic"
    env = dict(base_env, PYTHONPATH=str(ic))
    r = subprocess.run([sys.executable, "-m", "pytest", "-q", "-p", "no:cacheprovider",
                        "test_ic_group_manager.py"], cwd=ic, env=env,
                       capture_output=True, text=True, timeout=900)
    if "No module named pytest" in (r.stderr + r.stdout):
        print("  SKIP  test_ic_group_manager.py  (pip install pytest to run it)")
    else:
        last = (r.stdout.strip().splitlines() or [""])[-1]
        fails += r.returncode != 0
        print(f"  {'PASS' if r.returncode == 0 else 'FAIL'}  test_ic_group_manager.py  {last}")
    return fails


def apply(root, dry):
    todo, done, bad = plan(root)
    print(f"Repo: {root}\n  to apply: {len(todo)}   already applied: {len(done)}   blocked: {len(bad)}")
    if bad:
        print("\nABORTED — nothing written. These files are not the expected version:")
        for p, why in bad:
            print(f"  {p}: {why}")
        print("\nThis script targets v11.4.0 (optionally plus the TMA patch or the 20261026 script). "
              "Share the files above and the fix can be rebased onto your version.")
        return 2
    if dry:
        for f in todo:
            print(f"  would {'create' if f['is_new'] else 'update'}  {f['path']}")
        print("\nDry run OK — nothing written.")
        return 0
    for f in todo:
        p = root / f["path"]
        existed = p.exists()
        if p.exists():
            bak = p.with_name(p.name + ".bak-" + TAG)
            if not bak.exists():
                shutil.copy2(p, bak)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(zlib.decompress(base64.b64decode(f["data"])))
        if sha(p) != f["new_sha"]:
            sys.exit(f"Write verification failed for {f['path']} — run --revert.")
        f["_created"] = not existed
        print(f"  {'updated' if existed else 'created'}  {f['path']}")
    new_files = [f["path"] for f in todo if f.get("_created")]
    if new_files:
        man = root / MANIFEST
        prev = set(man.read_text().split()) if man.exists() else set()
        man.write_text("\n".join(sorted(prev | set(new_files))) + "\n")
    print(f"\nApplied {len(todo)} file(s). Backups: *.bak-{TAG}")
    return 0


MANIFEST = ".live_exit_e2e_20261027.created"


def revert(root):
    man = root / MANIFEST
    created = set(man.read_text().split()) if man.exists() else set()
    n = 0
    for f in FILES:
        p = root / f["path"]
        bak = p.with_name(p.name + ".bak-" + TAG)
        if bak.exists():
            shutil.copy2(bak, p); bak.unlink(); n += 1
            print(f"  restored {f['path']}")
        elif f["path"] in created and sha(p) == f["new_sha"]:   # created by this script
            p.unlink(); n += 1
            print(f"  removed  {f['path']}")
    if man.exists():
        man.unlink()
    print(f"Reverted {n} file(s). Restart the backend.")
    return 0


if __name__ == "__main__":
    ap = argparse.ArgumentParser(description="Scalp App live-exit hardening (2026-10-26)")
    ap.add_argument("--repo"); ap.add_argument("--dry-run", action="store_true")
    ap.add_argument("--revert", action="store_true"); ap.add_argument("--no-tests", action="store_true")
    a = ap.parse_args()
    root = find_root(a.repo)
    if a.revert:
        sys.exit(revert(root))
    rc = apply(root, a.dry_run)
    if rc or a.dry_run or a.no_tests:
        sys.exit(rc)
    fails = run_tests(root)
    print("\nALL TESTS PASSED — restart the backend, then paper-test each strategy."
          if not fails else f"\n{fails} TEST FILE(S) FAILED — run with --revert, and share the output.")
    sys.exit(1 if fails else 0)
